import { describe, test, expect } from 'vitest';
import { ZimmCartItem } from './product-item.css';
import { breakpoints } from 'app/theme/foundation';

/**
 * Recipe wiring — SFCC-795 §11.2 pass criterion 3. Reads the exported recipe function directly
 * (resolved at both `hasError` states) so these assert the real resolved token references, not a
 * rendered component's computed style (jsdom does not reliably resolve media-query-scoped
 * custom-property values).
 */
const DESKTOP_MEDIA_QUERY = `@media (min-width: ${breakpoints.md})`;

describe('ZimmCartItem — recipe wiring (Item Details gap / hasError)', () => {
  test('details gap is the existing 12px desktop token by default (hasError omitted)', () => {
    const styles = ZimmCartItem.baseStyle({});
    const details = styles.details as Record<string, unknown>;
    const desktop = details[DESKTOP_MEDIA_QUERY] as Record<string, unknown>;
    expect(desktop.gap).toBe('var(--zimm-scale-s)');
    // Mobile step is untouched by hasError — asserted here too so a future change to the
    // default branch can't silently widen the mobile value as a side effect.
    expect(details.gap).toBe('var(--zimm-scale-xl)');
  });

  test('details gap is the existing 12px desktop token when hasError is explicitly false', () => {
    const styles = ZimmCartItem.baseStyle({ hasError: false });
    const desktop = (styles.details as Record<string, unknown>)[DESKTOP_MEDIA_QUERY] as Record<string, unknown>;
    expect(desktop.gap).toBe('var(--zimm-scale-s)');
  });

  test('details gap widens to the 16px token when hasError is true, mobile gap unaffected', () => {
    const styles = ZimmCartItem.baseStyle({ hasError: true });
    const details = styles.details as Record<string, unknown>;
    const desktop = details[DESKTOP_MEDIA_QUERY] as Record<string, unknown>;
    expect(desktop.gap).toBe('var(--zimm-scale-m)');
    expect(details.gap).toBe('var(--zimm-scale-xl)');
  });

  test('row and info parts are unaffected by hasError', () => {
    const withError = ZimmCartItem.baseStyle({ hasError: true });
    const withoutError = ZimmCartItem.baseStyle({ hasError: false });
    expect(withError.row).toEqual(withoutError.row);
    expect(withError.info).toEqual(withoutError.info);
  });
});

// Source: Zimmermann Design System 2026 (Handover tokens/colors.css).
// Brand primitive and semantic alias colour tokens. The alias tier below
// references the primitive tier via plain object lookups (`grey[900]`)
// rather than retyping each hex value a second time.

const grey = {
  black: 'black',
  900: '#191919',
  800: '#282828',
  700: '#454545',
  600: '#666666',
  500: '#707070',
  300: '#969696',
  200: '#d1d1d1',
  100: '#e6e6e6',
  white: '#ffffff',
};

const ivory = {
  400: '#f2e9e0',
  300: '#fbf5ef',
  200: '#f6f4f1',
  100: '#f9f8f6',
};

const coral = { 500: '#f98f8c' };
const green = { 500: '#2d5a3d' };
const orange = { 500: '#d67600' };
const red = { 500: '#9c0000' };

// Opacity (base: grey/900 #191919)
const opacity = {
  50: 'rgba(25, 25, 25, 0.50)',
  40: 'rgba(25, 25, 25, 0.40)',
  30: 'rgba(25, 25, 25, 0.30)',
  15: 'rgba(25, 25, 25, 0.15)',
};

export const colors = {
  // ---- Brand / Primitive ----
  grey,
  ivory,
  coral,
  green,
  orange,
  red,
  opacity,

  // ---- Alias / Semantic: Background ----
  background: {
    '01': ivory[100],
    '02': ivory[200],
    '03': ivory[300],
    '04': ivory[400],
    '05': grey[900],
    '06': grey[800],
    '07': grey.white,
  },
  // ---- Alias / Semantic: Text ----
  text: {
    default: grey[900],
    inverse: grey.white,
    // Handover contradicts itself here: tokens/colors.css says #969696 "confirmed",
    // but tokens.md and contract/zimm-contract.js say #939393 and still flag it
    // unresolved. Shipping the colors.css value (grey[300]); confirm with the UI designer.
    inverseGrey: grey[300],
    secondary: grey[600],
    muted: grey[300],
  },
  // ---- Alias / Semantic: Border ----
  border: {
    default: grey[100],
    secondary: grey[200],
    focus: grey[900],
    forms: grey[500],
    error: red[500], // no Handover counterpart; retained for form validation use
  },
  // ---- Alias / Semantic: Status ----
  status: {
    success: green[500],
    error: red[500],
    errorBackground: coral[500],
    storeClosed: orange[500],
  },
  // ---- Alias / Semantic: Link ----
  link: {
    default: grey[900],
    hover: grey[500],
  },
  // ---- Alias / Semantic: Icon ----
  icon: {
    default: grey[900],
    disabled: grey[200],
  },
  // ---- Alias / Semantic: Action: Primary ----
  action: {
    primary: {
      bgDefault: grey[900],
      bgHover: grey[300],
      bgPressed: grey[700],
      bgDisabled: grey[200],
      bgFocused: grey.black,
      text: grey.white,
      textDisabled: grey[300],
    },
    secondary: {
      border: grey[900],
      bgHover: ivory[100],
      text: grey[900],
      textInverse: grey.white,
      textDisabled: grey[300],
    },
  },
};

// Spacing scale — source of truth: Figma node 2081:52901 (Design-Workspace > Spacing)
// Added to theme.space via extendTheme — Chakra's numeric defaults are preserved.
// Values are in rem so spacing scales with a user's root font-size / browser zoom
// (WCAG 1.4.4). Border widths (below) intentionally stay in px: hairline geometry
// shouldn't scale with zoom.

// prettier-ignore
export const spacing = {
  '3xs': '0.125rem', // 2px
  '2xs': '0.25rem',  // 4px
  xs:    '0.5rem',   // 8px
  s:     '0.75rem',  // 12px
  m:     '1rem',     // 16px
  l:     '1.25rem',  // 20px
  xl:    '1.5rem',   // 24px
  '2xl': '2rem',     // 32px
  '3xl': '2.5rem',   // 40px
  '4xl': '4rem',     // 64px
  '5xl': '5rem',     // 80px
  '6xl': '8rem',     // 128px
  '7xl': '10rem',    // 160px
} as const;

// Border widths — source of truth: Handover tokens/spacing.css (--zimm-border-width-default).
// Registered as theme.borderWidths; the CSS-var twin already exists in zimmTokens.ts.
export const borderWidths = {
  default: '1px',
} as const;

// Focus-ring outline offsets — hairline geometry, stays px like border widths above.
// `secondary` clears the 1px border on the secondary button variant (Handover
// button.md §focus) — the name describes that variant, not a generic scale step,
// since nothing else currently needs a third offset value.
export const focusRingOffsets = {
  default: '2px',
  secondary: '3px',
} as const;

  fontWeight: fontWeights.medium,
  lineHeight: lineHeights.xs,
  letterSpacing: letterSpacings.sm,
},
// Default/Caption (.zimm-text-caption)
caption: {
  fontFamily: FONT_MEDIUM,
  fontSize: fontSizes['3xs'],
  fontWeight: fontWeights.medium,
  lineHeight: lineHeights['2xs'],
  letterSpacing: letterSpacings.sm,
},
// ---- Links ----
// ZIM/Link-lg (.zimm-text-link-lg): uppercase + underline
linkLg: {

// Futura Round IS self-hosted — two faces (400, 500) ship from overrides/app/static/fonts/,
// declared by theme/fontFace.tsx. The stack below is the fallback chain, used only where the
// self-hosted face has not loaded. See frozenFiles.md > Design System.
// (Upstream source: Handover tokens/typography.css.)
// Fallbacks mirror the prototype's font stack so Century Gothic / Gill Sans renders
// on machines where Futura Round is unavailable — much closer to the brand look than Arial.
export const FONT_REGULAR =
  "'Futura Round', 'Futura LT Pro', 'Futura', 'Century Gothic', 'Gill Sans', 'Trebuchet MS', Arial, sans-serif";
export const FONT_MEDIUM =
  "'Futura Round', 'Futura LT Pro', 'Futura', 'Century Gothic', 'Gill Sans', 'Trebuchet MS', Arial, sans-serif";

